    snapshot: z
      .array(
        learningFile
          .extend({
            digest: suiteDigest,
            bytes: z
              .number()
              .int()
              .min(0)
              .max(64 * 1024),
          })
          .strict(),
      )
      .max(100),
    snapshotDigest: suiteDigest,
    observation: suiteJson,
    checks: z
      .array(
        z
          .object({
            id,
            kind: z.enum(['exists', 'text', 'json', 'status']),
            passed: z.boolean(),
            actual: suiteJson,
            error: z.string().max(200).nullable(),
          })
          .strict(),
      )
      .max(30),
    demo: learningDemo,
    error: z
      .object({ code: z.string().max(100), message: z.string().max(200) })
      .strict()
      .nullable(),
  })
  .strict();
